package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.apache.commons.lang3.text.translate.CharSequenceTranslator;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CharSequenceTranslator.with()
 */
public class CharSequenceTranslator_with_TriageGen2Test {

    /**
     * Mock implementation of CharSequenceTranslator to verify aggregation logic.
     */
    private static class MockTranslator extends CharSequenceTranslator {
        private final String replacement;

        MockTranslator(String replacement) {
            this.replacement = replacement;
        }

        @Override
        public int translate(CharSequence input, int index, StringWriter out) throws IOException {
            out.write(replacement);
            return replacement.length();
        }

        @Override
        public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
            out.write(replacement);
            return replacement.length();
        }
    }

    @Test
    public void testWith_NoArguments() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("A");

        // Act
        CharSequenceTranslator result = base.with();

        // Assert
        // The result should be an AggregateTranslator containing [base]
        // Since the method signature uses varargs, with() results in translators.length = 0
        // newArray size = 0 + 1 = 1. newArray[0] = base.
        StringWriter sw = new StringWriter();
        result.translate("test", sw);
        Assert.assertEquals("A", sw.toString());
    }

    @Test
    public void testWith_SingleArgument() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("A");
        CharSequenceTranslator extra = new MockTranslator("B");

        // Act
        CharSequenceTranslator result = base.with(extra);

        // Assert
        // Result should be AggregateTranslator containing [base, extra]
        // AggregateTranslator applies translators in order.
        StringWriter sw = new StringWriter();
        result.translate("test", sw);
        Assert.assertEquals("AB", sw.toString());
    }

    @Test
    public void testWith_MultipleArguments() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("1");
        CharSequenceTranslator t1 = new MockTranslator("2");
        CharSequenceTranslator t2 = new MockTranslator("3");
        CharSequenceTranslator t3 = new MockTranslator("4");

        // Act
        CharSequenceTranslator result = base.with(t1, t2, t3);

        // Assert
        StringWriter sw = new StringWriter();
        result.translate("test", sw);
        Assert.assertEquals("1234", sw.toString());
    }

    @Test
    public void testWith_NullArgumentInVarargs() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("A");
        CharSequenceTranslator nullTranslator = null;

        // Act
        // Passing null as an element in the varargs array
        CharSequenceTranslator result = base.with(nullTranslator);

        // Assert
        // The AggregateTranslator will attempt to call translate on the null element,
        // which should throw a NullPointerException.
        try {
            StringWriter sw = new StringWriter();
            result.translate("test", sw);
            Assert.fail("Should have thrown NullPointerException");
        } catch (NullPointerException e) {
            // Success
        }
    }

    @Test
    public void testWith_ReturnsNewInstance() {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("A");
        CharSequenceTranslator extra = new MockTranslator("B");

        // Act
        CharSequenceTranslator result1 = base.with(extra);
        CharSequenceTranslator result2 = base.with(extra);

        // Assert
        // Ensure that it creates a new AggregateTranslator instance each time
        Assert.assertNotSame("Each call to with() should return a new instance", result1, result2);
    }
}
